import{_ as l,H as a,f as i,i as p}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"13 | ETL：让数据从“原始”到“可用”","description":"","frontmatter":{},"headers":[{"level":2,"title":"ETL 的本质与核心概念","slug":"etl-的本质与核心概念","link":"#etl-的本质与核心概念","children":[]},{"level":2,"title":"Extract：数据提取的实践要点","slug":"extract-数据提取的实践要点","link":"#extract-数据提取的实践要点","children":[]},{"level":2,"title":"Transform：数据转换的核心技巧","slug":"transform-数据转换的核心技巧","link":"#transform-数据转换的核心技巧","children":[{"level":3,"title":"数据清洗","slug":"数据清洗","link":"#数据清洗","children":[]},{"level":3,"title":"数据标准化","slug":"数据标准化","link":"#数据标准化","children":[]},{"level":3,"title":"字段派生","slug":"字段派生","link":"#字段派生","children":[]},{"level":3,"title":"多数据源整合","slug":"多数据源整合","link":"#多数据源整合","children":[]},{"level":3,"title":"ID-Mapping：打通用户数据的关键","slug":"id-mapping-打通用户数据的关键","link":"#id-mapping-打通用户数据的关键","children":[]}]},{"level":2,"title":"Load：数据加载的策略选择","slug":"load-数据加载的策略选择","link":"#load-数据加载的策略选择","children":[]},{"level":2,"title":"ETL 开发的最佳实践","slug":"etl-开发的最佳实践","link":"#etl-开发的最佳实践","children":[]},{"level":2,"title":"ETL 的技术实现","slug":"etl-的技术实现","link":"#etl-的技术实现","children":[]},{"level":2,"title":"案例：通过统一日志规范，将 ETL 前置","slug":"案例-通过统一日志规范-将-etl-前置","link":"#案例-通过统一日志规范-将-etl-前置","children":[{"level":3,"title":"案例背景与痛点","slug":"案例背景与痛点","link":"#案例背景与痛点","children":[]},{"level":3,"title":"解决方案：制定统一日志规范，前置 “T” 环节","slug":"解决方案-制定统一日志规范-前置-t-环节","link":"#解决方案-制定统一日志规范-前置-t-环节","children":[]},{"level":3,"title":"新模式下的效果","slug":"新模式下的效果","link":"#新模式下的效果","children":[]}]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"大数据应用实战/13｜ETL：让数据从“原始”到“可用”.md","filePath":"大数据应用实战/13｜ETL：让数据从“原始”到“可用”.md","lastUpdated":1795555553000}'),t={name:"大数据应用实战/13｜ETL：让数据从“原始”到“可用”.md"};function n(r,e,o,s,h,d){return a(),i("div",null,[...e[0]||(e[0]=[p(`<h1 id="_13-etl-让数据从-原始-到-可用" tabindex="-1">13 | ETL：让数据从“原始”到“可用” <a class="header-anchor" href="#_13-etl-让数据从-原始-到-可用" aria-label="Permalink to &quot;13 | ETL：让数据从“原始”到“可用”&quot;">​</a></h1><p>你好，我是曹犟。</p><p>在上一节课中，我们学习了数据模型，了解了如何将业务需求转化为合理的数据结构。有了好的数据模型，接下来的问题是：如何让原始数据按照这个模型组织起来？这就是今天要讨论的核心话题——ETL。</p><p>对于 ETL 的重要性，我想举一个真实的例子。在神策的项目交付中，ETL 相关的成本占到了总成本的 70% 以上，远超系统部署和培训等其他环节。而且神策所做的项目，已经是数据模型相当标准，应用范围非常明确的项目了。</p><p>由此可以看出，ETL 是数据治理中最重要的环节，也是数据从“原始”到“可用”的必经之路。数据模型再完美，如果 ETL 做不好，数据就无法准确、及时地流转到该去的地方。</p><h2 id="etl-的本质与核心概念" tabindex="-1">ETL 的本质与核心概念 <a class="header-anchor" href="#etl-的本质与核心概念" aria-label="Permalink to &quot;ETL 的本质与核心概念&quot;">​</a></h2><p>ETL 是 Extract、Transform、Load 三个英文单词的缩写，分别代表数据的提取、转换和加载。这三个步骤构成了对数据进行预处理的完整链路。</p><ul><li><p>Extract：从各种数据源提取数据。这些数据源可能是关系型数据库、数据仓库、日志文件、API 接口、消息队列等。</p></li><li><p>Transform：对提取的数据进行清洗、转换和整合。包括去除脏数据、统一字段格式、多源数据 Join 和 Union、计算派生字段、ID-Mapping 等。</p></li><li><p>Load：将处理好的数据加载到目标系统。目标系统从逻辑上可以是数据仓库、数据湖等，是为特定应用准备的数据存储。</p></li></ul><p>回顾第 11 节课中所讲的数据分层概念，每一层之间的数据流转都需要 ETL。而第 12 节课讲的数据模型，则决定了 Transform 环节的转换规则应该如何设计以及 Load 的目标结构。</p><p>在第 10 节课中，我们也讨论了 ETL 和 ELT 的区别。传统 ETL 适合数据仓库场景，因为入库前必须完成数据清洗和转换，保证写入的都是高质量、符合模型定义的数据。ELT 则是先提取，直接加载原始数据，然后再在目标系统中进行转换。这种方式更适合数据湖场景，可以快速把数据存起来，按需处理。</p><p>在湖仓一体架构中，则往往是两种方式结合使用。对于已经明确数据模型和应用场景的数据，采用 ETL 方式严格管理；对于探索性数据，采用 ELT 方式灵活处理。</p><p>不同数据源（如客户端、日志文件、数据库等）的数据采集技术手段，以及近年来流行的通过CDC 方式进行数据表增量抽取的内容，我们在第 3 节课中已有过详细讨论，感兴趣的同学可以回顾一下。这节课，我们将更多侧重于从数据治理视角进行学习。</p><h2 id="extract-数据提取的实践要点" tabindex="-1">Extract：数据提取的实践要点 <a class="header-anchor" href="#extract-数据提取的实践要点" aria-label="Permalink to &quot;Extract：数据提取的实践要点&quot;">​</a></h2><p>Extract 是 ETL 的第一步，看似简单，但实践中有很多需要注意的地方。</p><p>全量还是抽样：这是 Extract 环节的一个重要选择。全量抽取简单直接，抽取数据源中所有数据，用于后续的加工和处理，适用于规模没那么大，或者价值密度足够高的数据。而抽样则是按照一定的规则只抽取部分数据，适用于数据过大，价值密度不够高的数据。</p><p>确定某一类数据应该抽样还是全量抽取，应该从应用场景出发。例如，同样是用客户端 SDK采集用户行为，如果是用户的购买、支付等核心行为，我们需要做精确的统计与留档，则应该全量采集；而如果是用户的浏览等非核心行为，我们可以按照用户 ID 进行抽样，只采集 1/8用户的行为，在统计这些行为的指标时，按照抽样比例反算回去即可。</p><p>质量检测：数据抽取阶段的质量检测是整个质量保障体系的第一道防线。越早发现问题，修复成本越低。在这个阶段，就应该开始针对数据的完整性、一致性、及时性等进行校验。如果发现问题，可以选择告警后继续，或者直接终止任务。这部分的内容我们会在第 14 节课具体讨论。</p><p>安全合规：数据抽取环节可能涉及大量敏感数据的访问和传输。在这个阶段，就应该开始对数据进行必要的脱敏和加密操作。</p><p>血缘与追踪：在数据抽取阶段建立完善的血缘关系和追踪机制，是后续问题排查和影响分析的基础。这个阶段需要记录的信息包括：数据来自哪个源系统、具体是哪张表或哪个文件、抽取的时间范围、使用的抽取方式（全量还是增量）、抽取的数据量等。这些信息共同形成了数据的“出生证明”。</p><p>性能优化：这个阶段的性能优化主要考虑两个方面。一是减少对源系统的影响。例如，只在业务低峰期执行抽取任务，只读数据库的从库而不是主库，采集数据用异步传输方案，谨慎控制抽取的频率与并发等。二是提高抽取效率。例如，把大表分成多个分片同时读取，使用批量传输减少网络交互次数，再比如数据压缩后再传输等。</p><h2 id="transform-数据转换的核心技巧" tabindex="-1">Transform：数据转换的核心技巧 <a class="header-anchor" href="#transform-数据转换的核心技巧" aria-label="Permalink to &quot;Transform：数据转换的核心技巧&quot;">​</a></h2><p>Transform 是 ETL 中最复杂、最核心的环节，也是最能体现数据治理水平的地方。我们来看看这个环节需要完成的主要任务。</p><h3 id="数据清洗" tabindex="-1">数据清洗 <a class="header-anchor" href="#数据清洗" aria-label="Permalink to &quot;数据清洗&quot;">​</a></h3><p>数据清洗是处理脏数据的过程。现实世界的数据很少是完美的，总会有各种各样的问题。典型的数据清洗任务包括：</p><ul><li><p>空值处理：业务系统中某些字段可能允许为空，但在数据分析中可能需要填充默认值。比如用户未填写城市信息，可以根据 IP 地址推断，或者标记为“未知”。</p></li><li><p>数据去重：可能由业务系统的 bug 导致，也可能是多次导入造成。需要根据业务主键去重，保留最新或最完整的记录。</p></li><li><p>异常值处理：需要结合特定的业务字段进行判断。比如用户年龄字段，如果出现 200 岁或-10 岁，明显是错误数据，需要清洗掉或者标记为异常。</p></li></ul><h3 id="数据标准化" tabindex="-1">数据标准化 <a class="header-anchor" href="#数据标准化" aria-label="Permalink to &quot;数据标准化&quot;">​</a></h3><p>数据标准化则是将不同来源的不同类型的数据转换为统一的格式和标准。包括：</p><ul><li><p>字段命名统一：不同业务系统中，同一个概念可能有不同的名称。前面课程提到的用户 ID的例子就是典型。</p></li><li><p>数据类型统一：不同源系统中的同一个字段可能格式不一致，需要进行统一。</p></li><li><p>文本编码统一：这是 CJK（汉字、日文、韩文）语言特有的问题，需要将这类文本编码从UTF-8、GBK 不同格式进行统一。</p></li><li><p>度量单位统一：即对金额、长度、重量等类型的字段采用统一的单位。</p></li><li><p>格式统一：对日期、时间等字段，有的是 “2024-01-01”，有的是 “20240101”，有的是时间戳，需要使用统一的格式。</p></li><li><p>汇率、时区统一：这是目前出海和国际化业务普遍碰到的问题，并且不仅仅是 ETL，在应用时也需要考虑。在 Transform 时，时区信息本身是需要作为一个字段保留的，时间则应该统一。而货币，则一般需要按照事件发生时候的汇率进行统一，不过原始币值也建议保留，因为有些时候可能也需要按照查询时的汇率做换算。</p></li></ul><h3 id="字段派生" tabindex="-1">字段派生 <a class="header-anchor" href="#字段派生" aria-label="Permalink to &quot;字段派生&quot;">​</a></h3><p>除了上面介绍的对已有字段的处理之外，我们很多时候还需要根据已有的字段生成新的字段，这种生成方式有：</p><ul><li><p>类型转换：比如把字符串转成数字，把时间戳转成日期格式。需要注意处理转换失败时的异常情况，比如&quot;abc&quot;无法转成数字。</p></li><li><p>字段映射：根据数据模型的定义，将源字段映射到目标字段。可能是一对一映射，也可能是多对一（多个源字段合并成一个目标字段），或者一对多（一个源字段拆分成多个目标字段）。</p></li><li><p>计算派生：根据已有字段计算出新字段。比如根据生日计算年龄，根据订单金额和数量计算单价。这些计算逻辑需要和业务方确认，确保准确性。</p></li></ul><h3 id="多数据源整合" tabindex="-1">多数据源整合 <a class="header-anchor" href="#多数据源整合" aria-label="Permalink to &quot;多数据源整合&quot;">​</a></h3><p>上面介绍的三种 Transform 的常见操作，都是对单个数据源中单条数据的操作，而在实际的过程中，我们很多时候都需要将多个数据源的数据进行关联、合并。</p><ul><li><p>数据源关联，也就是表 Join。比如将订单表和用户表 Join，可以得到订单的用户信息。实现时候需要考虑 Join 的方式（inner join、outer join）、join key 的选择、join 失败的处理。</p></li><li><p>数据源合并，也就是表 Union。比如多个业务线的订单数据合并成统一的订单表。需要处理字段不一致、数据重复等问题。</p></li></ul><h3 id="id-mapping-打通用户数据的关键" tabindex="-1">ID-Mapping：打通用户数据的关键 <a class="header-anchor" href="#id-mapping-打通用户数据的关键" aria-label="Permalink to &quot;ID-Mapping：打通用户数据的关键&quot;">​</a></h3><p>在精细化运营时代，对用户数据的采集、分析和应用，已经成为最重要的一种大数据应用。因此，在 Transform 部分的最后，我们要讨论一个比较特殊的数据处理问题，也就是 ID-Mapping，就是识别出同一个用户在不同系统、不同渠道的不同数据源中的身份。</p><p>在企业的不同系统、不同渠道中，同一个用户可能有多个不同的标识。在网站上，通常用CookieID 标识未登录的匿名用户，而用户登录之后，则一般都会有登录 ID（下面简称UserID）来更准确地识别用户身份。而对于 iOS、安卓、微信小程序这些渠道，也有自己的各种匿名用户标识方案，如 AndroidID、IDFA、OpenID、UnionID 等。</p><p>而除了这些第一方流量以外，我们使用的第三方平台，如天猫、京东或者配送平台等，会有限度地提供部分用户信息，例如下单信息、配送信息、退货信息等，这些数据中通过手机号、地址等有时候也可以识别出用户的身份。</p><p>如果不建立这些 ID 之间的映射关系，就无法追踪用户完整的行为路径，无法做到跨渠道的用户分析和洞察。</p><p>目前的 ID-Mapping 方案，从逻辑上，核心是以一个或者多个可信的 ID 为基础，以其它 ID 与这个 ID 的关系为桥梁，构建一个树状的 ID 体系。</p><p>例如，对于一个有网页、iOS App、安卓 App、微信小程序的等各种终端的产品，我们选择这个产品本身的统一登录标识 UserID 作为基础。而当用户在网页上注册或者主动自动登录时，我们可以记录一条 CookieID 与 UserID 的映射关系，同理，如果用户在其它终端发生登录行为时，我们同样可以记录这种映射关系。多条映射关系，共同构成一棵映射树。</p><p>下图简单标识了这种多对一的映射关系。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/13/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/13/1.png" alt=""></a></p><p>当有了这个映射树之后，在 Transform 的过程中，如果用户已经是登录状态，则行为里面必然有 UserID 这个字段；而如果用户不是登录状态，则可以在这个字段中补充 UserID 这个字段。特别地，如果这个行为发生在映射树构建之前，则在必要时候还需要往前回溯数据，补充字段。</p><p>在后续的分析和应用时，就可以用 UserID 来贯穿这同一个用户所有终端的行为。当然，有时候单独切换分析主体，例如特意用 CookieID 或者 IDFA 等作为用户标识，在不同的分析场景也是有意义的。</p><p>除了这种多对一的映射场景外，有些时候还会碰到多对多的情况。例如，同样一个浏览器的CookieID，先后会有两个不同的 UserID 完成登录。对于这种场景应该如何处理，未登录状态下的行为应该归属于哪个 UserID，则需要根据实际的业务需求来构建规则。</p><p>同时，除了这种一层对应关系之外，有些时候还会有带嵌套的对应关系，例如同一个用户在微信小程序体系下，一个 UnionID 对应多个 OpenID，一个 UserID 对应多个 UnionID。以及有些时候构建了映射关系后还需要解绑等，这些复杂情况无法一一列举，有兴趣可以私下交流。</p><h2 id="load-数据加载的策略选择" tabindex="-1">Load：数据加载的策略选择 <a class="header-anchor" href="#load-数据加载的策略选择" aria-label="Permalink to &quot;Load：数据加载的策略选择&quot;">​</a></h2><p>Load 是 ETL 的最后一步，将处理好的数据写入目标系统。在 Load 过程中，从数据治理角度，有以下一些问题需要注意。</p><p>首先是加载策略，也就是根据目标表的更新方式，有几种不同的加载策略。</p><p>覆盖写入（Overwrite）是最简单的方式，直接替换目标表的数据。适合全量加载或者分区覆盖的场景。比如每天的订单数据按日期分区，每天只覆盖当天分区。如果维度表的更新非常频繁，那么采用全量覆盖的方式会更简单高效。</p><p>追加写入（Append）是在目标表后面添加新数据，不修改已有数据。适合日志类数据、行为类等大数据流的事务型数据。</p><p>Upsert 是更新或插入的意思。如果记录已存在就更新，不存在就插入。这是最灵活但也最复杂的方式。实现 Upsert 需要根据主键判断记录是否存在，然后执行相应操作。维度表的更新，Upsert 用得比较多。需要根据自然键（业务主键）判断维度是否已存在，然后决定是插入新记录还是更新现有记录。</p><p>选择哪种方式，取决于数据量和数据的语义，同时也应该跟实际选择的存储和查询方案相结合。</p><p>其次则是分区加载策略。</p><p>其次，对于大规模数据，分区是必不可少的优化手段。最常见的是按时间分区，比如按天、按月，还可以按其他维度分区。比如按地区、按产品类别等。分区加载的设计，其核心思想和我们在第 5 节课讲到的存储分桶优化非常相似。可以说，它们是从不同角度看待同一个问题。</p><p>分区加载时需要注意几个问题。一是分区值的生成，需要统一规范；二是分区的粒度选择，太细会有太多小文件，太粗又起不到优化效果；三是跨分区的数据需要特殊处理。</p><p>第三则是加载的性能优化。加载阶段的性能优化主要包括几个方面。</p><ul><li><p>批量加载。一次写入多条记录，减少 IO 次数。大多数数据库和存储系统都支持批量写入API。并行加载。如果目标表有分区，可以并行加载不同分区。即使没有分区，也可以把数据分成多份并行写入。</p></li><li><p>合理选择文件格式。列式存储格式如 Parquet、ORC，比行式存储更节省空间，查询性能也更好。如果目标系统支持，应该优先选择列式存储。压缩。对数据进行压缩可以减少存储空间和 IO 开销。需要在压缩率和压缩速度之间权衡。</p></li><li><p>控制事务大小。如果在事务中写入太多数据，可能导致事务失败或者锁等待。需要把大事务拆分成小事务。</p></li></ul><h2 id="etl-开发的最佳实践" tabindex="-1">ETL 开发的最佳实践 <a class="header-anchor" href="#etl-开发的最佳实践" aria-label="Permalink to &quot;ETL 开发的最佳实践&quot;">​</a></h2><p>经过多年的实践，我总结了一些 ETL 开发的最佳实践。</p><p>首先是幂等性设计，即同一个操作执行多次，结果和执行一次相同。这是 ETL 任务必须具备的特性。因为 ETL 任务可能因为各种原因失败，需要重跑。而要实现幂等性，关键是在加载阶段处理好重复数据。对于追加写入的场景，可以在插入前先删除目标表中已有的数据。对于分区表，可以先删除对应分区再写入。对于 Upsert 场景，天然具备幂等性。</p><p>其次是可重跑设计。在日常实践中，我们经常会因为数据源出错、修改处理逻辑等原因，需要重跑特定时间分区的 ETL 任务。所以一个 ETL 任务一定要能够接受日期等作为任务的输入参数，而不能硬编码或者基于当前系统时间。同时，上下游任务的依赖关系要清晰。重跑某个任务时，应该能够自动识别并重跑其下游任务，保证数据一致性。</p><p>第三则是需要有完善的错误处理机制。对可预见的错误要有明确的处理策略。比如数据类型转换失败，是跳过这条数据，还是记录错误日志，还是终止任务？要记录详细的错误日志。包括错误发生的时间、错误类型、具体的数据内容等。要有告警机制。任务失败或者数据异常时，及时通知相关人员。告警不能太频繁，否则会被忽略；也不能太迟钝，否则问题发现不及时。要有恢复机制。对于可恢复的错误，比如网络抖动导致的连接失败，应该自动重试。重试要有次数限制和间隔时间，避免无限重试或者频繁重试加剧问题。</p><p>第四，ETL 任务需要有完善的调度与依赖管理能力。目前比较流行的开源系统如DolphinScheduler 等都是很好的选择。</p><p>最后，在实际的实践中，会碰到一些常见的陷阱。上面已经提到过的多时区问题和字符串编码问题就是典型。除此之外，我们还会碰到数据倾斜问题，如果某个 key 的数据量特别大，会导致单个任务处理时间过长，拖慢整体进度。需要对这种情况做特殊处理，比如把大 key 单独处理。NULL 值的处理，SQL 中 NULL 的语义比较特殊，在关联、分组等操作中，NULL 的行为需要特别注意。精度损失问题，浮点数运算可能有精度损失，金额等重要数据应该用定点数（如 decimal 类型）。</p><h2 id="etl-的技术实现" tabindex="-1">ETL 的技术实现 <a class="header-anchor" href="#etl-的技术实现" aria-label="Permalink to &quot;ETL 的技术实现&quot;">​</a></h2><p>在之前的内容中，我更多是从数据治理的角度来介绍 ETL 的业务逻辑。在这里，我们从技术角度出发，并且结合之前在第 6 节课程的内容，简单讨论一下具体的技术实现。</p><p>对于流式系统，除了 Union 和 Join 等多数据源整合以外，其余的 Transform 的工作，在类似于 Flink 这些计算引擎中都能比较方便的实现。而流式处理，其实应该在计算逻辑上就应该尽量规避跨数据源的 Union 或 Join。如果必须要做，也只能牺牲一部分精度，在有限的时间窗口内完成多数据源的 Join，或者是在 Union 语义下调整多数据源的数据顺序。</p><p>对于批量系统，对于有明确 Schema 约束的数据，还是应该按照 ETL 的模式，使用类似于SeaTunnel 这样的工具，或者自己开发批量计算任务，在完成数据处理后再入库。而对于其它探索类的数据源，则在进行简单处理之后，先入库，再使用计算引擎提供的能力，在必要时候对数据进行二次加工就好。</p><h2 id="案例-通过统一日志规范-将-etl-前置" tabindex="-1">案例：通过统一日志规范，将 ETL 前置 <a class="header-anchor" href="#案例-通过统一日志规范-将-etl-前置" aria-label="Permalink to &quot;案例：通过统一日志规范，将 ETL 前置&quot;">​</a></h2><p>为了帮你更具体地理解 ETL 在真实世界中的应用和演进，我分析一个亲身经历的案例：如何通过统一日志规范，将 ETL 工作“前置”，从而极大地提升效率。</p><h3 id="案例背景与痛点" tabindex="-1">案例背景与痛点 <a class="header-anchor" href="#案例背景与痛点" aria-label="Permalink to &quot;案例背景与痛点&quot;">​</a></h3><p>之前课程介绍过百度的 UDW 系统，需要将搜索、贴吧、知道、百科等数十条产品线的后端模块所产生的大量的用户行为日志，按照上一节课介绍的 event 宽表这个数据模型，统一处理再入库。</p><p>在最初的阶段，处理方式是“烟囱式”的，我们对每一条产品线都开发一套独立的 ETL 流程。这个方式存在以下问题。</p><ul><li><p>重复开发：每接入一个新的产品线，就要写一套新的 ETL 任务，去处理各不相同的数据格式，工作量巨大且枯燥。虽然在开发过程中，我们对工作进行了必要的抽象，形成了 ETL框架 + 配置文件 + 自定义任务的方式，但本质上依然是不同产品线不同任务。</p></li><li><p>维护困难：当时用于记录产品线日志格式的文档就有很多份，同时任何一个产品线的日志格式发生微小变更，都需要相应的修改代码，否则会导致对应的 ETL 任务失败。维护成本非常高。</p></li><li><p>资源浪费：几十个 ETL 任务并行，每一个任务都有很多处理逻辑，跑起来占用的计算资源很多，而且其中很多逻辑是有相似性的。</p></li></ul><h3 id="解决方案-制定统一日志规范-前置-t-环节" tabindex="-1">解决方案：制定统一日志规范，前置 “T” 环节 <a class="header-anchor" href="#解决方案-制定统一日志规范-前置-t-环节" aria-label="Permalink to &quot;解决方案：制定统一日志规范，前置 “T” 环节&quot;">​</a></h3><p>面对这些痛点，我们意识到，问题的根源在于数据产生的源头是“无序”的。与其在下游费力地“救火”，先污染后治理，不如在源头就把秩序建立起来。于是，我们启动了一个全局项目：制定全公司统一的日志规范。</p><p>这个方案的核心思想，就是把 ETL 中最复杂的“Transform”环节，尽可能地前置到“Extract”之前，也就是业务系统打印日志的那一刻。</p><p>具体是怎么做的呢？</p><ul><li>定义统一的日志结构：我们设计了一套全公司统一的日志 schema，并使用 Protobuf 来定</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>义。其中包含公司级的公共字段，比如：event_time （事件时间）， user_id （统一用</span></span>
<span class="line"><span>户 ID）， event_name （事件名称），product_line （产品线标识）等。也允许各个业</span></span></code></pre></div><ul><li><p>务方通过扩展字段来定义产品线级别的公共字段和特有字段。Protobuf 格式本身也具有更好的自解释性，同时代码的前后兼容性也更好。</p></li><li><p>提供统一的 Logging SDK：我们为公司所有主流的编程语言都开发了统一的 LoggingSDK。业务方的研发同学只需要调用这个 SDK，像打印普通日志一样，传入符合规范的结构化数据即可。SDK 会自动完成数据校验、序列化。统一开发的 LogAgent 模块，也会将这些日志自动发送到统一的数据总线（一个类似于 Kafka 的百度自研的消息队列）。</p></li><li><p>建立统一的日志格式变更规范：当产品线需要变更相应的日志 schema 时，有相对完整的评审规范，避免无序变更。</p></li></ul><h3 id="新模式下的效果" tabindex="-1">新模式下的效果 <a class="header-anchor" href="#新模式下的效果" aria-label="Permalink to &quot;新模式下的效果&quot;">​</a></h3><p>引入这套体系后，数据团队不再需要连接几十个不同的数据库或日志文件系统。他们唯一的、标准的提取来源，就是数据总线中的规范化日志。Transform 的工作量也大大减少，传统的“数据清洗”“格式统一”“字段派生”等工作几乎消失了。这个环节的核心任务，就只剩下了 ID-Mapping 和一些轻度的数据补充，比如根据 IP 地址补充地理位置信息等。</p><p>这个 “ETL 前置”的方案取得了巨大的成功：</p><ul><li><p>研发效率：新业务接入数据分析平台的周期，从几周缩短到了几天。数据工程师不再是“ETL 民工”，可以投入到更有价值的数据模型建设和数据产品开发中。</p></li><li><p>数据时效性：写入到数据总线中的规范化日志已经基本可用了，时效性要求高的应用可以直接订阅，极端情况下数据延迟可以降低到分钟以内。</p></li><li><p>数据质量：在源头统一了规范，避免了下游各种五花八门的解析错误，数据质量和一致性得到了根本性的保障。</p></li></ul><p>这个案例告诉我们，数据工程师不能机械地照搬传统的 ETL 思路，而是需要将数据治理的思维贯穿到从数据产生到数据消费的全链路中。在数据产生的源头就建立起规范和秩序，往往能起到事半功倍的效果。</p><p>这个数据规范从源头做起的认知，也变成了后来我们创立神策数据时的一个核心设计思路。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>今天我们深入学习了 ETL，这是数据从“原始”到“可用“的关键过程。</p><p>对于数据开发工程师，掌握 ETL 技术是核心技能，希望这节课能帮你深入理解数据 ETL 的原理和最佳实践，设计出高效、健壮的 ETL 流程。</p><p>对于数据产品经理，理解 ETL 能帮你更准确地评估需求的实现难度和周期，更好地和开发团队沟通，避免提出不合理的需求。</p><p>对于数据分析师，了解 ETL 过程能让你知道数据是怎么来的，有哪些清洗和转换，从而更准确地理解数据的含义，避免误用数据。</p><p>最后，还是按照惯例，用一个表格总结本节课的核心内容，希望能够帮你复习。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/13/2.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/13/2.jpeg" alt=""></a></p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><ul><li><p>在你的组织中，ETL 流程中最大的痛点是什么？是性能问题、数据质量问题，还是开发和维护成本问题？你们是如何解决的？</p></li><li><p>在实施 ETL 解决方案时，除了技术成本，你认为最大的“隐性成本”可能是什么？如何向业务方量化 ETL 投入的商业价值？</p></li><li><p>随着人工智能和机器学习的兴起，你认为未来的 ETL 流程会发生哪些变革？AI 是否能自动化 ETL 的某些环节，或者会带来新的数据处理挑战？</p></li></ul><p>欢迎在留言区分享你的思考和经验。下节课，我们将讨论数据质量管理，看看如何从问题到体系构建，掌握数据质量管理的全流程要点。</p>`,99)])])}const c=l(t,[["render",n]]);export{u as __pageData,c as default};
